result=None
for k in range(goal['min_count'],goal['max_count']+1):
 for combo in combinations(options,k):
  ids=[o['id'] for o in combo]
  owners=[o['owner'] for o in combo]
  if len(set(owners))!=len(owners): continue
  cost_sum=0
  quality_sum=0
  for o in combo:
   cost_sum=cost_sum+o['cost']
   quality_sum=quality_sum+o['quality']
  if cost_sum>goal['sum_bounds']['cost']['max']: continue
  if quality_sum<goal['sum_bounds']['quality']['min']: continue
  all_ids=[]
  for o in combo:
   all_ids=all_ids+[o['id']]
  requires_ok=True
  for o in combo:
   for r in o['requires']:
    found=False
    for id_ in all_ids:
     if r==id_:
      found=True
      break
    if not found:
     requires_ok=False
     break
   if not requires_ok:
    break
  if not requires_ok:
   continue
  # no_conflicts is false, so conflicts allowed
  sorted_combo=sorted(combo,key=lambda x:(x['rank'],x['id']))
  ids_sorted=[]
  for o in sorted_combo:
   ids_sorted=ids_sorted+[o['id']]
  if valid(ids_sorted):
   result=ids_sorted
   break
 if result is not None:
  break
